CREATE TABLE IF NOT EXISTS counts (day TEXT NOT NULL, district TEXT NOT NULL, n INTEGER NOT NULL, PRIMARY KEY (day, district));
CREATE TABLE IF NOT EXISTS limits (key TEXT NOT NULL, slot INTEGER NOT NULL, n INTEGER NOT NULL, PRIMARY KEY (key, slot));
CREATE TABLE IF NOT EXISTS subscribers (email TEXT PRIMARY KEY, token TEXT NOT NULL UNIQUE, district TEXT NOT NULL, region INTEGER NOT NULL, confirmed INTEGER NOT NULL DEFAULT 0, created INTEGER NOT NULL);
